/**
 * Game route — `/game/[id]`.
 *
 * Resolves the id from the generated game registry and renders the game's
 * screen through its lazy loader (`gameScreenLoaders`, generated by
 * `scripts/generate-game-registry.mjs`). Falls back to NotReady states for
 * unknown ids or registered-but-not-yet-implemented games.
 *
 * Note: Tutorial persistence is available via getDb().tutorials (see task 5.1).
 * Games use the in-memory store by default; the persistent store can be injected
 * via the tutorialStore prop when the component types are updated to accept it.
 */

import { useLocalSearchParams } from 'expo-router';
import { lazy, Suspense } from 'react';
import { StyleSheet } from 'react-native';

import { ErrorBoundary } from '@/components/error-boundary';
import { GameNotReady } from '@/components/game-not-ready';
import { ScreenShell } from '@/components/screen-shell';
import { ThemedText } from '@/components/themed-text';
import { ThemedView } from '@/components/themed-view';
import { Radii, Spacing } from '@/constants/theme';
import { getGameDefinition } from '@/registry/registry';
import { gameScreenLoaders } from '@/registry/registry.generated';

export default function GameScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const game = getGameDefinition(id ?? '');

  if (!game) {
    return (
      <ScreenShell>
        <ThemedText type="title" testID="game-title">
          Game
        </ThemedText>
        <GameNotReady variant="not-found" />
      </ScreenShell>
    );
  }

  const loader = gameScreenLoaders[game.id];
  const GameScreenComponent = loader !== undefined ? lazy(loader) : undefined;

  return (
    <ScreenShell>
      <ThemedText type="title" testID="game-title">
        {game.name}
      </ThemedText>
      <ThemedView type="accentSoft" style={styles.categoryPill} testID="game-category">
        <ThemedText type="caption" themeColor="accent">
          {game.primaryCategory}
        </ThemedText>
      </ThemedView>
      {game.description ? (
        <ThemedText type="small" themeColor="textSecondary" testID="game-description">
          {game.description}
        </ThemedText>
      ) : null}
      {GameScreenComponent ? (
        <ErrorBoundary
          onError={(error, info) => {
            console.error(
              JSON.stringify({
                level: 'error',
                component: 'game-route',
                gameId: game.id,
                message: error.message,
                stack: error.stack,
                componentStack: info.componentStack,
              }),
            );
          }}
        >
          <Suspense fallback={<GameNotReady variant="loading" />}>
            <GameScreenComponent />
          </Suspense>
        </ErrorBoundary>
      ) : (
        <GameNotReady variant="not-implemented" />
      )}
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  categoryPill: {
    alignSelf: 'flex-start',
    borderRadius: Radii.pill,
    paddingVertical: Spacing.half,
    paddingHorizontal: Spacing.twoHalf,
  },
});
